// Contract types, schema validation, JCS and digests for packages/contracts (OM-02).
// Enums are generated by `make codegen-java` into src/generated/java (committed; CI fails on a diff).
plugins {
    `java-library`
}

dependencies {
    api(libs.jackson.databind)
    implementation(libs.json.schema.validator)
}

sourceSets {
    main {
        java.srcDir("src/generated/java")
    }
}

// Schemas ship on the classpath under contracts/, so validation never touches the network.
tasks.processResources {
    from(rootProject.file("packages/contracts")) {
        include("**/*.schema.json", "errors.json")
        exclude("examples/**", "py/**")
        into("contracts")
    }
}

// Tests read examples/ straight from the repo, the same files scripts/contracts_check.py reads.
tasks.test {
    systemProperty("contracts.root", rootProject.file("packages/contracts").absolutePath)
}
